arguments.file_text:
namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string FullName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Student ID must contain only letters, numbers, and hyphens.")]
    [StringLength(20)]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments =
        [
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics including statistics and analysis." },
            new() { Id = 3, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Code = "ENG", Name = "English", Description = "Literature, writing, and linguistic studies." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of past events, civilizations, and societal change." },
        ];

        _courses =
        [
            // Computer Science
            new()
            {
                Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
                Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control structures, functions, and basic data structures. No prior experience required.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Alice Chen",
                InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has over 15 years of teaching experience. Her research focuses on programming language design and CS education.",
                IsFeatured = true
            },
            new()
            {
                Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures and Algorithms",
                Description = "Study of essential data structures (lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.",
                Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Dr. Bob Martinez",
                InstructorBio = "Dr. Martinez earned his doctorate from Stanford. He has published extensively on algorithm optimization and competitive programming.",
                IsFeatured = false
            },
            new()
            {
                Id = 3, DepartmentId = 1, CourseCode = "CS 310", Title = "Database Systems",
                Description = "Covers relational database design, SQL, normalization, transaction processing, and an introduction to NoSQL databases.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Prof. Clara Nguyen",
                InstructorBio = "Prof. Nguyen is a database systems expert with industry experience at Oracle and Microsoft. She brings real-world case studies to the classroom.",
                IsFeatured = true
            },

            // Mathematics
            new()
            {
                Id = 4, DepartmentId = 2, CourseCode = "MATH 151", Title = "Calculus I",
                Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. David Park",
                InstructorBio = "Dr. Park is an award-winning educator with a passion for making calculus accessible. He received his Ph.D. from the University of Chicago.",
                IsFeatured = true
            },
            new()
            {
                Id = 5, DepartmentId = 2, CourseCode = "MATH 250", Title = "Linear Algebra",
                Description = "Vectors, matrices, linear transformations, eigenvalues, and applications. Essential for advanced work in science and engineering.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Dr. Emily Ross",
                InstructorBio = "Dr. Ross specializes in applied linear algebra and numerical methods. She has co-authored two widely adopted textbooks.",
                IsFeatured = false
            },

            // Physics
            new()
            {
                Id = 6, DepartmentId = 3, CourseCode = "PHYS 101", Title = "General Physics I",
                Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:00 PM", InstructorName = "Dr. Frank Okafor",
                InstructorBio = "Dr. Okafor's research is in condensed matter physics. He is known for his engaging demonstrations and innovative lab curriculum.",
                IsFeatured = false
            },
            new()
            {
                Id = 7, DepartmentId = 3, CourseCode = "PHYS 220", Title = "Modern Physics",
                Description = "Introduction to special relativity, quantum mechanics, atomic and nuclear physics. Prerequisites: PHYS 101, MATH 151.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Dr. Grace Liu",
                InstructorBio = "Dr. Liu is a theoretical physicist whose work on quantum information has been featured in Nature and Physical Review Letters.",
                IsFeatured = true
            },

            // English
            new()
            {
                Id = 8, DepartmentId = 4, CourseCode = "ENG 110", Title = "College Writing",
                Description = "Develops academic writing skills through essay composition, peer review, and revision. Emphasis on argumentation and clear prose.",
                Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Prof. Helen Torres",
                InstructorBio = "Prof. Torres is a published author and rhetoric scholar. She has mentored hundreds of students in developing their writing voice.",
                IsFeatured = false
            },
            new()
            {
                Id = 9, DepartmentId = 4, CourseCode = "ENG 240", Title = "American Literature",
                Description = "Survey of American literary works from the colonial period to the present. Explores themes of identity, democracy, and cultural change.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Dr. Ian Walsh",
                InstructorBio = "Dr. Walsh received his Ph.D. from Yale and specializes in 20th-century American fiction. He is the editor of the Midwest Literary Review.",
                IsFeatured = false
            },

            // History
            new()
            {
                Id = 10, DepartmentId = 5, CourseCode = "HIST 101", Title = "World History to 1500",
                Description = "A survey of major civilizations, events, and cultural developments from prehistory through the late medieval period.",
                Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Julia Adams",
                InstructorBio = "Dr. Adams is an ancient and medieval historian. Her recent book on trade routes in the ancient world was a finalist for the National Book Award.",
                IsFeatured = false
            },
            new()
            {
                Id = 11, DepartmentId = 5, CourseCode = "HIST 275", Title = "The Civil Rights Movement",
                Description = "In-depth study of the American Civil Rights Movement from the 1950s to 1970s. Examines key figures, legislation, and lasting impact.",
                Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Kevin Brooks",
                InstructorBio = "Dr. Brooks is a historian of race and social justice in America. He frequently consults for documentary filmmakers and museums.",
                IsFeatured = true
            },
        ];
    }

    public IReadOnlyList<Department> GetAllDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.Find(d => d.Id == id);

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.Find(c => c.Id == id);

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public string GetDepartmentName(int departmentId) =>
        _departments.Find(d => d.Id == departmentId)?.Name ?? "Unknown";
}

